from datasets import load_dataset
import json

# 加载 default、queries、corpus
cache_dir = "/data/share/project/shared_datasets/mteb/mteb___covid_retrieval"
ds_default = load_dataset("mteb/CovidRetrieval", "default", cache_dir=cache_dir)
ds_queries = load_dataset("mteb/CovidRetrieval", "queries", cache_dir=cache_dir)
ds_corpus = load_dataset("mteb/CovidRetrieval", "corpus", cache_dir=cache_dir)

# 建立 _id -> 整行 的映射，便于按 id 查找
# CovidRetrieval 的 queries/corpus 配置的 split 名为 dev（与 mteb/apps 里用 "queries"/"corpus" 作 split 名不同）
queries_list = ds_queries["dev"]
corpus_list = ds_corpus["dev"]
query_by_id = {row["_id"]: row for row in queries_list}
corpus_by_id = {row["_id"]: row for row in corpus_list}

# 从 default 的 dev 中随机抽取 5 条（CovidRetrieval 仅有 dev，无 test）
test_split = ds_default["dev"]
sampled_ds = test_split.shuffle(seed=123).select(range(5))
first_five = sampled_ds.to_dict()

print("=" * 80)
print("Default 数据集 dev 集合随机 5 条：query 与 corpus 具体内容")
print("=" * 80)

# 用于 Few_Shot_Example.py 兼容格式的列表
apps_few_shot_format = []

for i in range(5):
    query_id = first_five["query-id"][i]
    corpus_id = first_five["corpus-id"][i]
    score = first_five["score"][i]

    query_row = query_by_id[query_id]
    corpus_row = corpus_by_id[corpus_id]

    # 收集 Few_Shot_Example 兼容格式：query + Positive(corpus text)
    apps_few_shot_format.append({
        "query": query_row["text"],
        "Positive": corpus_row["text"]
    })

    print(f"\n【第 {i+1} 条】")
    print(f"  query-id:  {query_id}")
    print(f"  corpus-id: {corpus_id}")
    print(f"  score:     {score}")
    print("-" * 60)
    print("  QUERY 内容:")
    print(f"    {query_row['text']}")
    print("-" * 60)
    print("  CORPUS 内容:")
    print(f"    title: {corpus_row.get('title', '')}")
    text = corpus_row["text"]
    print(f"    text:  {text}")
    print("=" * 80)

# 输出 Few_Shot_Example.py 中 "apps" 兼容的 Python 结构（可直接复制到 Few_Shot_Example.py）
print("\n" + "=" * 80)
print("Few_Shot_Example 兼容格式（可复制到 Few_Shot_Example.py 的 \"covid_retrieval\" 键）：")
print("=" * 80)
print('    "covid_retrieval": ', end="")
print(json.dumps(apps_few_shot_format, indent=4, ensure_ascii=False))
print("=" * 80)


